COMP = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}

# ═════════════════════════ INHERIT: traits on the X chromosome ═════════════════════════

XLINK_SIMPLIFY = B('A gene on the X chromosome is followed. The father gives his X to his daughters and his Y to his sons; the mother gives one of her two X chromosomes to each child.', 'Se sigue un gen del cromosoma X. El padre da su X a sus hijas y su Y a sus hijos; la madre da uno de sus dos cromosomas X a cada hijo.')

inh_calico = inh_spec('inh-calico', B('Why calico cats are almost always female', 'Por qué los gatos calicó casi siempre son hembras'), B('A coat colour gene on the X chromosome', 'Un gen del color del pelaje en el cromosoma X'), 'advanced', 8, 'cell',
    B('Fill in the Punnett squares for a gene on the X chromosome of cats. Mothers have two X chromosomes (like Gg); fathers have one X and one Y (like GY).', 'Rellena los cuadros de Punnett de un gen del cromosoma X de los gatos. Las madres tienen dos cromosomas X (como Gg); los padres tienen un X y un Y (como GY).'),
    B('The gene for orange fur is on the X chromosome. A female with one orange and one black allele shows patches of both colours, which is the tortoiseshell or calico coat. A male has only one X, so he is orange or black.', 'El gen del pelo naranja está en el cromosoma X. Una hembra con un alelo naranja y uno negro muestra manchas de los dos colores, que es el pelaje carey o calicó. Un macho solo tiene un X, así que es naranja o negro.'),
    org('cat-calico', 'Domestic cat', 'Gato doméstico', 'Felis catus', B('A pet whose coat colour gene sits on the X chromosome.', 'Una mascota cuyo gen del color del pelaje está en el cromosoma X.'), MAMMAL + ['Carnivora', 'Felidae', 'Felis'], tissue='skin'),
    [ex('cell', B('Patches', 'Manchas'), B('Two colours in one cat', 'Dos colores en un gato'), B('In each cell of a female only one X chromosome stays active, chosen at random. In some patches it carries the orange allele and in others the black one, so the cat is a mosaic.', 'En cada célula de una hembra solo un cromosoma X queda activo, elegido al azar. En unas manchas lleva el alelo naranja y en otras el negro, así que la gata es un mosaico.')),
     ex('dna', B('Sex-linked', 'Ligado al sexo'), B('Males have one X', 'Los machos tienen un solo X'), B('A male gets his X from his mother and his Y from his father, so he shows whichever allele his mother passed on. The Y chromosome has no copy of the gene.', 'Un macho recibe su X de su madre y su Y de su padre, así que muestra el alelo que le pasó su madre. El cromosoma Y no tiene copia del gen.'))],
    dict(trait=B('Fur colour', 'Color del pelo'), alleles=['G', 'g', 'Y'], genotypes=['GG', 'Gg', 'gg', 'GY', 'gY'],
         phenotypes={'GG': 'orange_f', 'Gg': 'tortie', 'gg': 'black_f', 'GY': 'orange_m', 'gY': 'black_m'},
         labels={'orange_f': B('Orange female', 'Hembra naranja'), 'tortie': B('Tortoiseshell female', 'Hembra carey'), 'black_f': B('Black female', 'Hembra negra'), 'orange_m': B('Orange male', 'Macho naranja'), 'black_m': B('Black male', 'Macho negro')},
         scenarios=[
             sc('GG', 'gY', B('Orange mother', 'Madre naranja'), B('Black father', 'Padre negro'), B('An orange mother (GG) and a black father (gY) have kittens. What is the probability that a kitten is a tortoiseshell female?', 'Una madre naranja (GG) y un padre negro (gY) tienen gatitos. ¿Qué probabilidad hay de que un gatito sea una hembra carey?'), 'tortie',
                B('The cells are Gg, GY, Gg and GY. The daughters (Gg) are tortoiseshell and the sons (GY) are orange: 50% tortoiseshell females.', 'Las casillas son Gg, GY, Gg y GY. Las hijas (Gg) son carey y los hijos (GY) son naranjas: 50 % de hembras carey.')),
             sc('Gg', 'gY', B('Tortoiseshell mother', 'Madre carey'), B('Black father', 'Padre negro'), B('A tortoiseshell mother (Gg) and a black father (gY) have kittens. What is the probability that a kitten is an orange male?', 'Una madre carey (Gg) y un padre negro (gY) tienen gatitos. ¿Qué probabilidad hay de que un gatito sea un macho naranja?'), 'orange_m',
                B('The cells are Gg, GY, gg and gY. Only GY is an orange male: 25%.', 'Las casillas son Gg, GY, gg y gY. Solo GY es un macho naranja: 25 %.')),
             sc('gg', 'GY', B('Black mother', 'Madre negra'), B('Orange father', 'Padre naranja'), B('A black mother (gg) and an orange father (GY) have kittens. What is the probability that a kitten is a black male?', 'Una madre negra (gg) y un padre naranja (GY) tienen gatitos. ¿Qué probabilidad hay de que un gatito sea un macho negro?'), 'black_m',
                B('The cells are Gg, gY, Gg and gY. The sons (gY) are black and the daughters (Gg) are tortoiseshell: 50% black males.', 'Las casillas son Gg, gY, Gg y gY. Los hijos (gY) son negros y las hijas (Gg) son carey: 50 % de machos negros.'))]),
    [B('Write the mother\'s alleles on one side and the father\'s on the other, like always. A son gets the Y from his father.', 'Escribe los alelos de la madre a un lado y los del padre al otro, como siempre. Un hijo recibe la Y de su padre.'),
     B('A cell with Y is a male. A cell with two X alleles is a female: Gg is tortoiseshell.', 'Una casilla con Y es un macho. Una casilla con dos alelos X es una hembra: Gg es carey.'),
     B('Count the cells of the kind asked about: each is worth 25%.', 'Cuenta las casillas del tipo por el que preguntan: cada una vale un 25 %.')],
    **closing(B('Two colours, one cat', 'Dos colores, un gato'),
              B('You saw why tortoiseshell cats are females, and why a tortoiseshell male is very rare.', 'Has visto por qué los gatos carey son hembras, y por qué un macho carey es muy raro.'),
              B('The same logic explains why some conditions of people, such as red-green colour blindness, are more common in men: a man has no second X to hide the changed allele.', 'La misma lógica explica por qué algunos rasgos de las personas, como el daltonismo rojo-verde, son más comunes en hombres: un hombre no tiene un segundo X que esconda el alelo cambiado.'),
              B('In 2025 two teams found that the orange allele of cats is a deletion near a gene called ARHGAP36 on the X chromosome, which switches that gene on in pigment cells and turns the dark pigment off.', 'En 2025 dos equipos hallaron que el alelo naranja de los gatos es una deleción cerca de un gen llamado ARHGAP36 del cromosoma X, que activa ese gen en las células del pigmento y apaga el pigmento oscuro.'),
              B('X inactivation silences one X chromosome in each cell of a female. Because the choice is random and is passed on to the daughter cells, a female with two different alleles is a patchwork.', 'La inactivación del X silencia un cromosoma X en cada célula de una hembra. Como la elección es al azar y se transmite a las células hijas, una hembra con dos alelos distintos es un mosaico.'),
              [XLINK_SIMPLIFY, B('The white patches of a calico cat come from a different gene, which is not followed here.', 'Las manchas blancas de un gato calicó vienen de otro gen, que aquí no se sigue.')],
              [ref(['Kaelin, C. B.', 'McGowan, K. A.', 'Trotman, J. B.', 'et al.'], 2025, 'Molecular and genetic characterization of sex-linked orange coat color in the domestic cat', 'Current Biology', '10.1016/j.cub.2025.04.055')]))

inh_flies = inh_spec('inh-flies', B('White-eyed flies', 'Moscas de ojos blancos'), B('The fly that showed that genes sit on chromosomes', 'La mosca que demostró que los genes están en los cromosomas'), 'intermediate', 7, 'flask',
    B('Fill in the Punnett squares for the eye colour of fruit flies, a gene on the X chromosome: females have two X (like Ww), males have X and Y (like WY).', 'Rellena los cuadros de Punnett del color de ojos de las moscas de la fruta, un gen del cromosoma X: las hembras tienen dos X (como Ww), los machos X e Y (como WY).'),
    B('In 1910 a researcher found a single male fly with white eyes among thousands of red-eyed ones. The way the trait passed to the next generations showed that the gene sat on the X chromosome.', 'En 1910 un investigador encontró un único macho de ojos blancos entre miles de moscas de ojos rojos. La forma en que el rasgo pasaba a las generaciones siguientes mostró que el gen estaba en el cromosoma X.'),
    org('fly-white', 'Fruit fly', 'Mosca de la fruta', 'Drosophila melanogaster', B('A small fly that was the model of early genetics.', 'Una mosca pequeña que fue el modelo de la genética temprana.'), ['Animalia', 'Arthropoda', 'Insecta', 'Diptera', 'Drosophilidae', 'Drosophila'], tissue='eye'),
    [ex('flask', B('The fly', 'La mosca'), B('Fast, small and cheap', 'Rápida, pequeña y barata'), B('A fruit fly lives for a few weeks and a female lays hundreds of eggs, so many generations can be followed in a few months.', 'Una mosca de la fruta vive unas semanas y una hembra pone cientos de huevos, así que se pueden seguir muchas generaciones en unos meses.')),
     ex('dna', B('The surprise', 'La sorpresa'), B('White eyes only in males', 'Ojos blancos solo en machos'), B('In the second generation almost all the white-eyed flies were males. A trait that depends on the sex of the fly had to be on the sex chromosome.', 'En la segunda generación casi todas las moscas de ojos blancos eran machos. Un rasgo que depende del sexo de la mosca tenía que estar en el cromosoma sexual.'))],
    dict(trait=B('Eye colour', 'Color de los ojos'), alleles=['W', 'w', 'Y'], genotypes=['WW', 'Ww', 'ww', 'WY', 'wY'],
         phenotypes={'WW': 'red_f', 'Ww': 'red_f', 'ww': 'white_f', 'WY': 'red_m', 'wY': 'white_m'},
         labels={'red_f': B('Red-eyed female', 'Hembra de ojos rojos'), 'white_f': B('White-eyed female', 'Hembra de ojos blancos'), 'red_m': B('Red-eyed male', 'Macho de ojos rojos'), 'white_m': B('White-eyed male', 'Macho de ojos blancos')},
         scenarios=[
             sc('WW', 'wY', B('Red-eyed female', 'Hembra de ojos rojos'), B('White-eyed male', 'Macho de ojos blancos'), B('A red-eyed female (WW) and a white-eyed male (wY) have offspring. What is the probability that an offspring is a red-eyed female?', 'Una hembra de ojos rojos (WW) y un macho de ojos blancos (wY) tienen descendientes. ¿Qué probabilidad hay de que un descendiente sea una hembra de ojos rojos?'), 'red_f',
                B('The cells are Ww, WY, Ww and WY. Daughters (Ww) are red-eyed and sons (WY) are red-eyed: 50% are red-eyed females.', 'Las casillas son Ww, WY, Ww y WY. Las hijas (Ww) tienen ojos rojos y los hijos (WY) también: 50 % son hembras de ojos rojos.')),
             sc('Ww', 'WY', B('Red-eyed female, carries w', 'Hembra de ojos rojos, lleva w'), B('Red-eyed male', 'Macho de ojos rojos'), B('A red-eyed female that carries w (Ww) and a red-eyed male (WY) have offspring. What is the probability that an offspring is a white-eyed male?', 'Una hembra de ojos rojos que lleva w (Ww) y un macho de ojos rojos (WY) tienen descendientes. ¿Qué probabilidad hay de que un descendiente sea un macho de ojos blancos?'), 'white_m',
                B('The cells are WW, WY, Ww and wY. Only wY is a white-eyed male: 25%. This is the case that surprised the researcher.', 'Las casillas son WW, WY, Ww y wY. Solo wY es un macho de ojos blancos: 25 %. Es el caso que sorprendió al investigador.')),
             sc('Ww', 'wY', B('Red-eyed female, carries w', 'Hembra de ojos rojos, lleva w'), B('White-eyed male', 'Macho de ojos blancos'), B('A red-eyed female that carries w (Ww) and a white-eyed male (wY) have offspring. What is the probability that an offspring is a white-eyed female?', 'Una hembra de ojos rojos que lleva w (Ww) y un macho de ojos blancos (wY) tienen descendientes. ¿Qué probabilidad hay de que un descendiente sea una hembra de ojos blancos?'), 'white_f',
                B('The cells are Ww, WY, ww and wY. Only ww is a white-eyed female: 25%.', 'Las casillas son Ww, WY, ww y wY. Solo ww es una hembra de ojos blancos: 25 %.'))]),
    [B('Mothers give an X, fathers give an X to daughters and a Y to sons. A cell with Y is a male.', 'Las madres dan un X; los padres dan un X a las hijas y una Y a los hijos. Una casilla con Y es un macho.'),
     B('W is dominant: WW and Ww are red-eyed females. A male has only one allele: WY is red-eyed and wY is white-eyed.', 'W es dominante: WW y Ww son hembras de ojos rojos. Un macho solo tiene un alelo: WY tiene ojos rojos y wY ojos blancos.'),
     B('Count the cells of the kind asked about: each is worth 25%.', 'Cuenta las casillas del tipo por el que preguntan: cada una vale un 25 %.')],
    **closing(B('A gene with an address', 'Un gen con dirección'),
              B('You saw that a trait that is more common in one sex points to a gene on a sex chromosome.', 'Has visto que un rasgo más común en un sexo apunta a un gen en un cromosoma sexual.'),
              B('The fly became the model animal of genetics, and its work led to maps of genes on chromosomes and to several Nobel Prizes.', 'La mosca se convirtió en el animal modelo de la genética, y su trabajo llevó a mapas de genes en los cromosomas y a varios premios Nobel.'),
              B('Thomas Hunt Morgan reported the white-eyed male in 1910. Together with the pattern of inheritance, it gave the first clear proof that a particular gene lies on a particular chromosome, and earned him the 1933 Nobel Prize in Physiology or Medicine.', 'Thomas Hunt Morgan describió el macho de ojos blancos en 1910. Junto con el patrón de herencia, fue la primera prueba clara de que un gen concreto está en un cromosoma concreto, y le valió el Premio Nobel de Fisiología o Medicina de 1933.'),
              B('The white allele is a loss of function in a gene whose protein loads pigment into the eye cells. Females need two copies to be white-eyed; males, with a single X, need only one.', 'El alelo blanco es una pérdida de función de un gen cuya proteína carga pigmento en las células del ojo. Las hembras necesitan dos copias para tener ojos blancos; los machos, con un solo X, necesitan una.'),
              [XLINK_SIMPLIFY],
              [ref(['Morgan, T. H.'], 1910, 'Sex limited inheritance in Drosophila', 'Science', '10.1126/science.32.812.120')]))

# ═════════════════════════ MUTATION: four more everyday cases ═════════════════════════

SAME = lambda txt_en, txt_es: (txt_en, txt_es)
NOT_SILENT = B('Not here: the amino acid changes.', 'Aquí no: el aminoácido cambia.')
NOT_STOP = B('Not here: no stop signal appears.', 'Aquí no: no aparece ninguna señal de fin.')
NOT_MISSENSE = B('Not here: the codon turns into a stop.', 'Aquí no: el codón se convierte en una parada.')
MUT_SIMPLIFY = B('The real change is the one described, but the sequence around it is an invented short example.', 'El cambio real es el que se describe, pero la secuencia que lo rodea es un ejemplo corto inventado.')

mut_tiger = mut_spec('mut-tiger', B('Why some tigers are white', 'Por qué algunos tigres son blancos'), B('A swap in a pigment transporter', 'Un cambio en un transportador de pigmento'), 'intermediate', 5, 'cell',
    B('Pigment transporter gene (illustrative)', 'Gen de un transportador del pigmento (ilustrativo)'), 'ATGAAGGCTGGACTCCAA', 'ATGAAGGTTGGACTCCAA',
    B('A real change with an invented sequence. White tigers are not albino: they have blue eyes and dark stripes. They carry two copies of a swap of one amino acid, alanine for valine, in a protein that moves pigment materials in the cells.', 'Un cambio real con una secuencia inventada. Los tigres blancos no son albinos: tienen ojos azules y rayas oscuras. Llevan dos copias de un cambio de un aminoácido, alanina por valina, en una proteína que mueve materiales del pigmento en las células.'),
    {'silent': NOT_SILENT,
     'missense': B('GCT (Ala) became GTT (Val): one amino acid was swapped for another. This real change in a gene called SLC45A2 removes the red-yellow pigment of the fur, and the tiger is white.', 'GCT (Ala) pasó a GTT (Val): un aminoácido se cambió por otro. Este cambio real, en un gen llamado SLC45A2, quita el pigmento rojo y amarillo del pelaje, y el tigre es blanco.'),
     'nonsense': NOT_STOP},
    [ex('cell', B('The tiger', 'El tigre'), B('White, not albino', 'Blanco, no albino'), B('A white tiger has blue eyes and black or brown stripes. Albinos would have no pigment at all, so the cause is a different gene.', 'Un tigre blanco tiene los ojos azules y rayas negras o marrones. Un albino no tendría ningún pigmento, así que la causa es otro gen.')),
     ex('dna', B('The swap', 'El cambio'), B('Alanine to valine', 'De alanina a valina'), B('Alanine and valine are both small, but the swap, in the middle of the protein, makes it work worse. A tiger needs two copies to be white.', 'La alanina y la valina son pequeñas, pero el cambio, en medio de la proteína, la hace funcionar peor. Un tigre necesita dos copias para ser blanco.'))],
    [B('Compare the two rows letter by letter. Only one is different.', 'Compara las dos filas letra a letra. Solo una es distinta.'),
     B('Look at the codon that contains the changed letter, before and after.', 'Mira el codón que contiene la letra cambiada, antes y después.'),
     B('The change is in the third codon: GCT became GTT, so Ala became Val (missense).', 'El cambio está en el tercer codón: GCT pasó a GTT, así que Ala pasó a Val (de sentido erróneo).')],
    org('tiger-gene', 'Pigment transporter', 'Transportador del pigmento', 'Panthera tigris', B('A protein of the pigment cells of the tiger.', 'Una proteína de las células del pigmento del tigre.'), MAMMAL + ['Carnivora', 'Felidae', 'Panthera'], tissue='skin'),
    **closing(B('A white coat from a swap', 'Un pelaje blanco por un cambio'),
              B('You found a one-letter change that swaps an amino acid and makes a tiger white.', 'Has encontrado un cambio de una letra que sustituye un aminoácido y hace blanco a un tigre.'),
              B('White tigers in zoos come from a few related animals, which shows how a rare recessive allele spreads when relatives are bred together.', 'Los tigres blancos de los zoos vienen de unos pocos animales emparentados, lo que muestra cómo se extiende un alelo recesivo raro cuando se cruzan parientes.'),
              B('In 2013 a team showed that white tigers carry two copies of an A477V change in the gene SLC45A2, the same gene that is behind the cream colour of horses.', 'En 2013 un equipo mostró que los tigres blancos llevan dos copias de un cambio A477V en el gen SLC45A2, el mismo gen que está detrás del color crema de los caballos.'),
              B('A missense mutation swaps one amino acid for another. Here the protein carries less of the material needed for the red-yellow pigment, while the black stripes, made with another pigment, stay.', 'Una mutación de sentido erróneo cambia un aminoácido por otro. Aquí la proteína lleva menos del material necesario para el pigmento rojo y amarillo, mientras las rayas negras, hechas con otro pigmento, se mantienen.'),
              [MUT_SIMPLIFY],
              [ref(['Xu, X.', 'Dong, G.-X.', 'Hu, X.-S.', 'et al.'], 2013, 'The genetic basis of white tigers', 'Current Biology', '10.1016/j.cub.2013.04.054')]))

mut_dogfur = mut_spec('mut-dogfur', B('Why some dogs have long hair', 'Por qué algunos perros tienen el pelo largo'), B('A swap in a hair growth gene', 'Un cambio en un gen del crecimiento del pelo'), 'intermediate', 5, 'cell',
    B('Hair growth gene of dogs (illustrative)', 'Gen del crecimiento del pelo de los perros (ilustrativo)'), 'ATGGACTGTAACGTGGAG', 'ATGGACTTTAACGTGGAG',
    B('A real change with an invented sequence. A gene called FGF5 tells hair follicles when to stop growing. A swap of cysteine for phenylalanine in it makes the signal weaker, and the hair grows longer.', 'Un cambio real con una secuencia inventada. Un gen llamado FGF5 dice a los folículos del pelo cuándo dejar de crecer. Un cambio de cisteína por fenilalanina en él debilita la señal, y el pelo crece más.'),
    {'silent': NOT_SILENT,
     'missense': B('TGT (Cys) became TTT (Phe): one amino acid was swapped for another. This real change, called C95F, is found in many long-haired breeds.', 'TGT (Cys) pasó a TTT (Phe): un aminoácido se cambió por otro. Este cambio real, llamado C95F, se encuentra en muchas razas de pelo largo.'),
     'nonsense': NOT_STOP},
    [ex('cell', B('The coat', 'El pelaje'), B('Short or long', 'Corto o largo'), B('Hair grows in a cycle: it grows, stops and falls. In long-haired dogs the growing phase lasts longer.', 'El pelo crece en un ciclo: crece, se detiene y se cae. En los perros de pelo largo la fase de crecimiento dura más.')),
     ex('dna', B('The change', 'El cambio'), B('A cysteine less', 'Una cisteína menos'), B('The long-hair allele is recessive, as you saw with the dogs of the inheritance levels: it needs two copies.', 'El alelo del pelo largo es recesivo, como viste con los perros de los niveles de herencia: necesita dos copias.'))],
    [B('Compare the two rows letter by letter. Only one is different.', 'Compara las dos filas letra a letra. Solo una es distinta.'),
     B('Look at the codon that contains the changed letter, before and after.', 'Mira el codón que contiene la letra cambiada, antes y después.'),
     B('The change is in the third codon: TGT became TTT, so Cys became Phe (missense).', 'El cambio está en el tercer codón: TGT pasó a TTT, así que Cys pasó a Phe (de sentido erróneo).')],
    org('dog-fgf5', 'Dog', 'Perro', 'Canis lupus familiaris', B('A species with hundreds of breeds and several coat genes.', 'Una especie con cientos de razas y varios genes del pelaje.'), MAMMAL + ['Carnivora', 'Canidae', 'Canis'], tissue='hair follicle'),
    **closing(B('A longer coat', 'Un pelaje más largo'),
              B('You found a one-letter change that swaps an amino acid and lengthens the hair of a dog.', 'Has encontrado un cambio de una letra que sustituye un aminoácido y alarga el pelo de un perro.'),
              B('Tests for these genes help breeders predict the coat of puppies, and show how a few changes in a few genes explain much of the variety of dog breeds.', 'Las pruebas de estos genes ayudan a quien cría a predecir el pelaje de los cachorros, y muestran cómo unos pocos cambios en unos pocos genes explican gran parte de la variedad de razas de perro.'),
              B('In 2009 a team studied the DNA of hundreds of dogs of many breeds and found that three genes, among them FGF5, explain most of the variation in length, curl and furnishings of the coat.', 'En 2009 un equipo estudió el ADN de cientos de perros de muchas razas y halló que tres genes, entre ellos FGF5, explican la mayor parte de la variación de longitud, rizado y cejas y barba del pelaje.'),
              B('A missense mutation swaps one amino acid for another. Here the signal of FGF5 is weaker, so the hair follicles stay in their growing phase for longer.', 'Una mutación de sentido erróneo cambia un aminoácido por otro. Aquí la señal de FGF5 es más débil, así que los folículos del pelo permanecen más tiempo en su fase de crecimiento.'),
              [MUT_SIMPLIFY],
              [ref(['Cadieu, E.', 'Neff, M. W.', 'Quignon, P.', 'et al.'], 2009, 'Coat variation in the domestic dog is governed by variants in three genes', 'Science', '10.1126/science.1177808')]))

mut_muscle = mut_spec('mut-muscle', B('Cattle with double muscle', 'Vacas de doble músculo'), B('A swap in the brake of muscle growth', 'Un cambio en el freno del crecimiento muscular'), 'intermediate', 5, 'cell',
    B('Myostatin gene of cattle (illustrative)', 'Gen de la miostatina del ganado (ilustrativo)'), 'ATGCAGTGTGACGAGCTG', 'ATGCAGTATGACGAGCTG',
    B('A real change with an invented sequence. Myostatin is a protein that tells muscles to stop growing. In Piedmontese cattle a swap of cysteine for tyrosine disables it, and the animals have much more muscle.', 'Un cambio real con una secuencia inventada. La miostatina es una proteína que dice a los músculos que dejen de crecer. En el ganado piamontés un cambio de cisteína por tirosina la desactiva, y los animales tienen mucho más músculo.'),
    {'silent': NOT_SILENT,
     'missense': B('TGT (Cys) became TAT (Tyr): one amino acid was swapped for another. This real change, called C313Y, stops myostatin from working, and the muscles keep growing.', 'TGT (Cys) pasó a TAT (Tyr): un aminoácido se cambió por otro. Este cambio real, llamado C313Y, impide que la miostatina funcione, y los músculos siguen creciendo.'),
     'nonsense': NOT_STOP},
    [ex('cell', B('The brake', 'El freno'), B('Myostatin', 'La miostatina'), B('Every mammal makes myostatin. It keeps muscles from growing too much. Without it, the muscles of a calf grow far more, a trait called double muscling.', 'Todos los mamíferos fabrican miostatina. Evita que los músculos crezcan demasiado. Sin ella, los músculos de un ternero crecen mucho más, un rasgo llamado doble músculo.')),
     ex('dna', B('Different breeds', 'Razas distintas'), B('Different changes, the same effect', 'Cambios distintos, el mismo efecto'), B('Belgian Blue cattle have a short deletion in the same gene, and Piedmontese cattle have a swap of one amino acid. Both stop the brake from working.', 'El ganado azul belga tiene una deleción corta en el mismo gen, y el piamontés tiene un cambio de un aminoácido. Los dos impiden que el freno funcione.'))],
    [B('Compare the two rows letter by letter. Only one is different.', 'Compara las dos filas letra a letra. Solo una es distinta.'),
     B('Look at the codon that contains the changed letter, before and after.', 'Mira el codón que contiene la letra cambiada, antes y después.'),
     B('The change is in the third codon: TGT became TAT, so Cys became Tyr (missense).', 'El cambio está en el tercer codón: TGT pasó a TAT, así que Cys pasó a Tyr (de sentido erróneo).')],
    org('cattle-mstn', 'Myostatin', 'Miostatina', 'Bos taurus', B('A protein that limits the growth of muscles.', 'Una proteína que limita el crecimiento de los músculos.'), MAMMAL + ['Artiodactyla', 'Bovidae', 'Bos'], tissue='muscle'),
    **closing(B('A brake that fails', 'Un freno que falla'),
              B('You found a one-letter change that swaps an amino acid and disables the brake of muscle growth.', 'Has encontrado un cambio de una letra que sustituye un aminoácido y desactiva el freno del crecimiento muscular.'),
              B('Double-muscled cattle give lean meat, but calving is harder, so breeders weigh the benefit and the cost of the allele.', 'El ganado de doble músculo da carne magra, pero los partos son más difíciles, así que quien cría sopesa el beneficio y el coste del alelo.'),
              B('In 1997 a team reported that Belgian Blue and Piedmontese cattle carry different changes in the myostatin gene, which explains their double-muscled look.', 'En 1997 un equipo describió que el ganado azul belga y el piamontés llevan cambios distintos en el gen de la miostatina, lo que explica su aspecto de doble músculo.'),
              B('A missense mutation swaps one amino acid for another. The cysteine of this change takes part in the bond that holds the protein together, so the protein falls apart.', 'Una mutación de sentido erróneo cambia un aminoácido por otro. La cisteína de este cambio participa en el enlace que mantiene unida la proteína, así que la proteína se deshace.'),
              [MUT_SIMPLIFY],
              [ref(['Kambadur, R.', 'Sharma, M.', 'Smith, T. P.', 'Bass, J. J.'], 1997, 'Mutations in myostatin (GDF8) in double-muscled Belgian Blue and Piedmontese cattle', 'Genome Research', '10.1101/gr.7.9.910')]))

mut_wheat = mut_spec('mut-wheat', B('The short wheat that fed millions', 'El trigo bajo que alimentó a millones'), B('A stop codon at the start of a growth gene', 'Un codón de fin al comienzo de un gen del crecimiento'), 'advanced', 6, 'wheat',
    B('Wheat growth gene (illustrative)', 'Gen del crecimiento del trigo (ilustrativo)'), 'ATGAAGCGGGAGCAGGAAGACGGC', 'ATGAAGCGGGAGTAGGAAGACGGC',
    B('A real change with an invented sequence. The wheat of the Green Revolution was short and sturdy, and did not fall over under the weight of grain. Its dwarf genes carry a stop codon near the start of a gene that controls growth.', 'Un cambio real con una secuencia inventada. El trigo de la Revolución Verde era bajo y robusto, y no se tumbaba con el peso del grano. Sus genes enanos llevan un codón de fin cerca del comienzo de un gen que controla el crecimiento.'),
    {'silent': B('Not here: the codon turns into a stop.', 'Aquí no: el codón se convierte en una parada.'),
     'missense': NOT_MISSENSE,
     'nonsense': B('CAG (Gln) became TAG, a stop codon. The message ends very early, and the plant makes a changed form of the growth protein that the hormone gibberellin cannot switch off, so the stems stay short.', 'CAG (Gln) pasó a TAG, un codón de fin. El mensaje termina muy pronto, y la planta fabrica una forma cambiada de la proteína del crecimiento que la hormona giberelina no puede desactivar, así que los tallos se quedan cortos.')},
    [ex('grain', B('The wheat', 'El trigo'), B('Short and sturdy', 'Bajo y robusto'), B('Fertiliser made old, tall wheat grow too much and fall over. Short wheat could take more fertiliser and give more grain.', 'El abono hacía que el trigo antiguo, alto, creciera demasiado y se tumbara. El trigo bajo podía recibir más abono y dar más grano.')),
     ex('dna', B('The brake', 'El freno'), B('A growth protein that does not switch off', 'Una proteína del crecimiento que no se apaga'), B('The normal protein holds growth back until the hormone gibberellin removes it. The dwarf versions cannot be removed, so growth stays held back.', 'La proteína normal frena el crecimiento hasta que la hormona giberelina la elimina. Las versiones enanas no se pueden eliminar, así que el crecimiento sigue frenado.'))],
    [B('Compare the two rows letter by letter. Only one is different.', 'Compara las dos filas letra a letra. Solo una es distinta.'),
     B('Look at the codon that contains the changed letter, before and after. Is the new codon a stop?', 'Mira el codón que contiene la letra cambiada, antes y después. ¿El codón nuevo es de parada?'),
     B('The change is in the fifth codon: CAG became TAG, a stop (nonsense).', 'El cambio está en el quinto codón: CAG pasó a TAG, una parada (sin sentido).')],
    org('wheat-rht', 'Wheat', 'Trigo', 'Triticum aestivum', B('The cereal of most of the bread of the world.', 'El cereal de la mayor parte del pan del mundo.'), PLANT + ['Liliopsida', 'Poales', 'Poaceae', 'Triticum'], tissue='stem'),
    **closing(B('A stop that fed millions', 'Una parada que alimentó a millones'),
              B('You found a letter that creates a stop codon near the start of a gene, with an effect that is the opposite of what you might expect.', 'Has encontrado una letra que crea un codón de fin cerca del comienzo de un gen, con un efecto contrario a lo que podrías esperar.'),
              B('Short, sturdy wheat and rice varieties raised yields so much in the 20th century that the period is known as the Green Revolution.', 'Las variedades de trigo y arroz bajas y robustas elevaron tanto los rendimientos en el siglo XX que ese período se conoce como la Revolución Verde.'),
              B('In 1999 a team showed that the dwarf genes of Green Revolution wheat, Rht-B1b and Rht-D1b, carry changes that create stop codons near the start of the gene, and that the plants make a growth-holding protein that the hormone cannot remove.', 'En 1999 un equipo mostró que los genes enanos del trigo de la Revolución Verde, Rht-B1b y Rht-D1b, llevan cambios que crean codones de fin cerca del comienzo del gen, y que las plantas fabrican una proteína que frena el crecimiento y que la hormona no puede eliminar.'),
              B('A nonsense mutation usually breaks a protein. Here the cell restarts reading later in the message, so a shortened protein is made that lacks the part that the hormone recognises. It is a rare case where a stop codon makes a gene more active, not less.', 'Una mutación sin sentido suele romper una proteína. Aquí la célula reanuda la lectura más adelante en el mensaje, así que se fabrica una proteína acortada a la que le falta la parte que reconoce la hormona. Es un caso raro en que un codón de fin hace a un gen más activo, no menos.'),
              [MUT_SIMPLIFY],
              [ref(['Peng, J.', 'Richards, D. E.', 'Hartley, N. M.', 'et al.'], 1999, '‘Green revolution’ genes encode mutant gibberellin response modulators', 'Nature', '10.1038/22307')]))

# ═════════════════════════ PAIRING: PCR primers ═════════════════════════

PRIMER = 'AAGCTTGGCATCAGTA'
primer_partner = ' '.join(COMP[c] for c in PRIMER)
pair_primer = pair_spec('pair-primer', B('The primer that finds its place', 'El cebador que encuentra su sitio'), B('Sixteen letters to match a template', 'Dieciséis letras para casar con un molde'), 'intermediate', 5, 'dna', PRIMER,
    B('PCR starts with a short piece of DNA, the primer, that sticks to the start of the stretch to copy. Write the primer that pairs with this template.', 'La PCR empieza con un trozo corto de ADN, el cebador, que se pega al principio del tramo que se quiere copiar. Escribe el cebador que se empareja con este molde.'),
    B('Write the strand that pairs with this template, letter by letter. That strand is the primer.', 'Escribe la hebra que se empareja con este molde, letra a letra. Esa hebra es el cebador.'),
    [B('Go from left to right and pair each letter on its own.', 'Ve de izquierda a derecha y empareja cada letra por separado.'),
     B('A pairs with T and C pairs with G, in both directions.', 'A se une con T y C con G, en los dos sentidos.'),
     B('The partners are: ' + primer_partner + '.', 'Las parejas son: ' + primer_partner + '.')],
    [ex('dna', B('The primer', 'El cebador'), B('A short key for a long lock', 'Una llave corta para una cerradura larga'), B('A primer of about 20 letters sticks only where its partner letters are found, so it picks one stretch out of a whole genome.', 'Un cebador de unas 20 letras solo se pega donde están sus letras pareja, así que elige un tramo entre todo un genoma.')),
     ex('flask', B('The cycle', 'El ciclo'), B('Heat, cool, copy', 'Calentar, enfriar, copiar'), B('The DNA is heated to open the strands, cooled so the primers stick, and warmed a little so an enzyme can extend them. Each cycle doubles the copies.', 'El ADN se calienta para abrir las hebras, se enfría para que se peguen los cebadores y se templa un poco para que una enzima los alargue. Cada ciclo duplica las copias.'))],
    **closing(B('A primer that fits', 'Un cebador que encaja'),
              B('You wrote a primer by applying the pairing rules: the same rules that make PCR so specific.', 'Has escrito un cebador aplicando las reglas de emparejamiento: las mismas que hacen tan específica a la PCR.'),
              B('PCR primers are the heart of many tests: tracing food, checking a pet, finding a virus or comparing species.', 'Los cebadores de PCR son el corazón de muchas pruebas: rastrear alimentos, revisar una mascota, encontrar un virus o comparar especies.'),
              B('The PCR method was invented in 1983 by Kary Mullis, who received the 1993 Nobel Prize in Chemistry. Its power comes from the primers.', 'El método de la PCR lo inventó en 1983 Kary Mullis, que recibió el Premio Nobel de Química de 1993. Su poder viene de los cebadores.'),
              B('Hydrogen bonds hold A with T (two bonds) and G with C (three bonds). A primer with more G and C sticks more firmly.', 'Los enlaces de hidrógeno mantienen unidas A con T (dos enlaces) y G con C (tres enlaces). Un cebador con más G y C se pega con más fuerza.'),
              B('Strands are written in the same direction to keep it simple; real primers pair in opposite directions.', 'Las hebras se escriben en el mismo sentido para simplificar; los cebadores reales se emparejan en sentidos opuestos.'),
              []))

# ═════════════════════════ SEQUENCE: wine and a new crop ═════════════════════════

seq_wine = seq_spec('seq-wine', B('From grapes to red wine', 'De la uva al vino tinto'), B('Yeast does the middle of the work', 'La levadura hace la parte central del trabajo'), 'beginner', 5, 'bottle',
    B('Put the steps of making red wine in order, and see where the yeast comes in.', 'Pon en orden los pasos para hacer vino tinto y descubre dónde entra la levadura.'),
    B('Wine is grape juice that yeast has turned into alcohol. For red wine the skins stay in during fermentation, which is where the colour comes from.', 'El vino es zumo de uva que la levadura ha convertido en alcohol. En el vino tinto las pieles se quedan durante la fermentación, y de ahí sale el color.'),
    org('wine-yeast', 'Grapes and yeast', 'Uvas y levadura', 'Saccharomyces cerevisiae', B('The yeast of wine, bread and beer.', 'La levadura del vino, el pan y la cerveza.'), FUNGI + ['Saccharomyces'], tissue='grape must'),
    [ex('bottle', B('The grape', 'La uva'), B('Sugar in the skin and the juice', 'Azúcar en la piel y el jugo'), B('Ripe grapes contain about a fifth of their weight in sugar, and carry wild yeasts on their skin.', 'Las uvas maduras contienen cerca de una quinta parte de su peso en azúcar y llevan levaduras silvestres en la piel.')),
     ex('yeast', B('The yeast', 'La levadura'), B('Sugar to alcohol', 'De azúcar a alcohol'), B('Yeast ferments the sugar into alcohol and carbon dioxide. It needs warmth, and it stops when the sugar runs out or the alcohol gets too high.', 'La levadura fermenta el azúcar en alcohol y dióxido de carbono. Necesita calor, y se detiene cuando se acaba el azúcar o el alcohol sube demasiado.'))],
    [('harvest', B('Harvest the ripe grapes', 'Vendimiar las uvas maduras'), B('The grapes are full of sugar.', 'Las uvas están llenas de azúcar.'), NOTHING),
     ('crush', B('Crush the grapes with their skins', 'Estrujar las uvas con sus pieles'), B('The juice, the skins and the yeasts mix.', 'El jugo, las pieles y las levaduras se mezclan.'), B('There must be grapes first.', 'Primero tiene que haber uvas.')),
     ('ferment', B('Let the yeast ferment the sugar into alcohol', 'Dejar que la levadura fermente el azúcar en alcohol'), B('The must warms up and bubbles; the skins give colour.', 'El mosto se calienta y burbujea; las pieles dan color.'), B('The juice and the yeast have to be together first.', 'El jugo y la levadura tienen que estar juntos antes.')),
     ('press', B('Press the skins and separate the wine', 'Prensar las pieles y separar el vino'), B('The young wine is separated from the skins.', 'El vino joven se separa de las pieles.'), B('The sugar must have been fermented first.', 'El azúcar tiene que haberse fermentado antes.')),
     ('settle', B('Let the wine settle and draw it off the sediment', 'Dejar reposar el vino y trasegarlo del sedimento'), B('The wine becomes clearer.', 'El vino se aclara.'), B('The skins have to be pressed away first.', 'Las pieles tienen que haberse prensado antes.')),
     ('age', B('Age the wine in barrels or tanks', 'Criar el vino en barricas o depósitos'), B('Flavours change and soften.', 'Los sabores cambian y se suavizan.'), B('The wine has to be clear first.', 'El vino tiene que estar claro antes.')),
     ('bottle', B('Bottle the wine', 'Embotellar el vino'), B('The wine is ready to keep and to drink.', 'El vino está listo para guardar y beber.'), B('The wine has to be aged first.', 'El vino tiene que estar criado antes.'))],
    B('Wine', 'Vino'),
    [B('The yeast needs the juice first, and the wine can only be separated from the skins when fermentation has done its work.', 'La levadura necesita primero el jugo, y el vino solo se puede separar de las pieles cuando la fermentación ha hecho su trabajo.'),
     B('Harvest, crush, ferment, press, settle, age and bottle.', 'Vendimiar, estrujar, fermentar, prensar, reposar, criar y embotellar.'),
     B('Harvest → crush → ferment → press → settle → age → bottle.', 'Vendimiar → estrujar → fermentar → prensar → reposar → criar → embotellar.')],
    **closing(B('A chain with a microbe in the middle', 'Una cadena con un microbio en medio'),
              B('You followed the steps of wine making, with the yeast in the central step.', 'Has seguido los pasos de la elaboración del vino, con la levadura en el paso central.'),
              B('Wine is one of the oldest fermented foods, and wineries now choose their yeasts, as breweries and bakeries do, to control the flavour.', 'El vino es uno de los alimentos fermentados más antiguos, y las bodegas eligen hoy sus levaduras, como hacen las cervecerías y las panaderías, para controlar el sabor.'),
              B('Louis Pasteur showed in the 1860s that yeast cells carry out the fermentation of wine, and that other microbes spoil it.', 'Louis Pasteur mostró en la década de 1860 que las células de levadura llevan a cabo la fermentación del vino, y que otros microbios lo estropean.'),
              B('Red wine gets its colour from pigments in the skins, which dissolve in the alcohol as it forms. White wine is pressed before fermenting, so the skins stay out.', 'El vino tinto obtiene su color de pigmentos de las pieles, que se disuelven en el alcohol a medida que se forma. El vino blanco se prensa antes de fermentar, así que las pieles se quedan fuera.'),
              B('Many steps are left out, such as adding sulphites or the second fermentation that some wines have.', 'Se omiten muchos pasos, como añadir sulfitos o la segunda fermentación que tienen algunos vinos.'),
              []))

seq_crop = seq_spec('seq-crop', B('How a new crop variety is made', 'Cómo se hace una nueva variedad de cultivo'), B('From a gene to a field', 'De un gen a un campo'), 'advanced', 9, 'plant',
    B('Put in order the steps that lead from the idea of a new trait to seeds that farmers can buy.', 'Pon en orden los pasos que llevan de la idea de un rasgo nuevo a unas semillas que se pueden comprar.'),
    B('A crop that makes its own vitamin, or that resists a pest, takes years to develop. Each step has to be done before the next one makes sense.', 'Un cultivo que fabrica su propia vitamina, o que resiste una plaga, tarda años en desarrollarse. Cada paso tiene que hacerse antes de que el siguiente tenga sentido.'),
    org('crop-steps', 'A new crop variety', 'Una variedad nueva de cultivo', 'Plant biotechnology', B('The way from the laboratory to the field.', 'El camino del laboratorio al campo.'), ['Method'], tissue='plant cells'),
    [ex('plant', B('The goal', 'El objetivo'), B('A useful trait', 'Un rasgo útil'), B('Plants can be given a gene for a vitamin, a colour or a resistance. The gene has to get into the plant cells and the cells have to grow into a whole plant.', 'A las plantas se les puede dar un gen para una vitamina, un color o una resistencia. El gen tiene que entrar en las células de la planta y las células tienen que crecer hasta formar una planta entera.')),
     ex('bacterium', B('A helper', 'Un ayudante'), B('Agrobacterium', 'Agrobacterium'), B('A soil bacterium naturally moves some of its DNA into plant cells. Scientists replace that DNA with the gene they want.', 'Una bacteria del suelo pasa de forma natural parte de su ADN a las células de las plantas. Los científicos sustituyen ese ADN por el gen que quieren.'))],
    [('gene', B('Choose the gene for the new trait', 'Elegir el gen del rasgo nuevo'), B('The gene comes from another plant, a microbe or a design.', 'El gen viene de otra planta, de un microbio o de un diseño.'), NOTHING),
     ('build', B('Build a construct with the gene, a promoter and a terminator', 'Montar un constructo con el gen, un promotor y un terminador'), B('A circuit that a plant cell can read.', 'Un circuito que una célula de planta puede leer.'), B('The gene has to be chosen first.', 'El gen tiene que estar elegido antes.')),
     ('insert', B('Put the construct into plant cells with Agrobacterium', 'Introducir el constructo en células de planta con Agrobacterium'), B('Some cells take up the new DNA.', 'Algunas células incorporan el ADN nuevo.'), B('The construct has to exist first.', 'El constructo tiene que existir antes.')),
     ('select', B('Grow the cells on a medium that kills the unmodified ones', 'Cultivar las células en un medio que mata a las no modificadas'), B('Only the cells that received the DNA survive.', 'Solo sobreviven las células que recibieron el ADN.'), B('The DNA has to be in the cells first.', 'El ADN tiene que estar en las células antes.')),
     ('regrow', B('Regenerate whole plants from the surviving cells', 'Regenerar plantas enteras a partir de las células supervivientes'), B('Hormones in the medium make the cells grow roots and shoots.', 'Las hormonas del medio hacen que las células echen raíces y brotes.'), B('There must be surviving cells.', 'Tiene que haber células supervivientes.')),
     ('green', B('Test the plants in a greenhouse', 'Probar las plantas en un invernadero'), B('Check that the gene is there and that the trait works.', 'Comprobar que el gen está y que el rasgo funciona.'), B('The plants have to be grown first.', 'Las plantas tienen que haberse cultivado antes.')),
     ('field', B('Run field trials over several seasons', 'Hacer ensayos de campo durante varias temporadas'), B('The plants face real weather, pests and soils.', 'Las plantas se enfrentan al clima, las plagas y los suelos reales.'), B('The greenhouse tests have to be good first.', 'Las pruebas del invernadero tienen que ser buenas antes.')),
     ('approve', B('Pass the safety review and multiply the seeds', 'Superar la revisión de seguridad y multiplicar las semillas'), B('The authorities check the safety, and seeds are produced for sale.', 'Las autoridades comprueban la seguridad y se producen semillas para vender.'), B('The field trial data are needed first.', 'Antes hacen falta los datos de los ensayos de campo.'))],
    B('New variety', 'Variedad nueva'),
    [B('The path goes from a gene to cells, to plants, to a field and, at the end, to the market.', 'El camino va de un gen a células, a plantas, a un campo y, al final, al mercado.'),
     B('Gene, construct, insert, select, regrow, greenhouse, field and approval.', 'Gen, constructo, introducir, seleccionar, regenerar, invernadero, campo y aprobación.'),
     B('Gene → construct → insert → select → regrow → greenhouse → field → approval.', 'Gen → constructo → introducir → seleccionar → regenerar → invernadero → campo → aprobación.')],
    **closing(B('A long road made short', 'Un camino largo hecho corto'),
              B('You followed the whole road of a new crop variety, from a gene to the seeds, and saw why it takes years.', 'Has seguido todo el camino de una variedad nueva de cultivo, de un gen a las semillas, y has visto por qué tarda años.'),
              B('Knowing the steps helps to discuss new crops with facts: what is tested, when, and by whom.', 'Conocer los pasos ayuda a hablar de cultivos nuevos con datos: qué se prueba, cuándo y quién lo hace.'),
              B('The first genetically modified plants were made in the early 1980s with Agrobacterium. The first tomato, the Flavr Savr, reached the shops in 1994.', 'Las primeras plantas modificadas genéticamente se hicieron a principios de los años ochenta con Agrobacterium. El primer tomate, el Flavr Savr, llegó a las tiendas en 1994.'),
              B('The selection step uses a marker gene that gives the cell resistance to a substance in the medium. Only cells with the construct survive, and a balance of hormones brings back a whole plant from a single cell.', 'El paso de selección usa un gen marcador que da a la célula resistencia a una sustancia del medio. Solo sobreviven las células con el constructo, y un equilibrio de hormonas devuelve una planta entera a partir de una sola célula.'),
              B('Other methods, such as shooting DNA on tiny particles or editing with CRISPR, change a few of these steps.', 'Otros métodos, como disparar ADN en partículas diminutas o editar con CRISPR, cambian algunos de estos pasos.'),
              []))

write_levels([inh_calico, inh_flies, mut_tiger, mut_dogfur, mut_muscle, mut_wheat, pair_primer, seq_wine, seq_crop])
